const openedAt = new Date($("Ticket ID").first().json.opened_at);
const priority = $("Dept select").first().json.output.priority;

let slaHours = 24;

if (priority === "High") slaHours = 2;
else if (priority === "Medium") slaHours = 8;

const slaDeadline = new Date(openedAt);
slaDeadline.setHours(slaDeadline.getHours() + slaHours);

return [{
  json: {
    sla_deadline: slaDeadline.toISOString()
  }
}];

const staticData = $getWorkflowStaticData('global');
const agent = $json.assigned_agent;

if (!staticData.agentTickets) staticData.agentTickets = {};
if (!staticData.agentTickets[agent]) staticData.agentTickets[agent] = [];

staticData.agentTickets[agent].push($json.ticket_id);

return [{ json: $json }];

const staticData = $getWorkflowStaticData('global');
const agentTickets = staticData.agentTickets || {};

return Object.keys(agentTickets).map(agent => ({
  json: {
    agent: agent,
    ticket_id: agentTickets[agent]
  }
}));

const allItems = $input.all();

return allItems.map(item => ({
  json: {
    ...item.json,
    hasTickets: Array.isArray(item.json.ticket_id) && item.json.ticket_id.length > 0
  }
}));

const allItems = $input.all();

if (allItems.length === 0) {
  return [{ json: { ticket_id: null, issue_title: null, sla_deadline: null, noTickets: true } }];
}

return allItems;

const ids = $json.ticket_id || [];
const titles = $json.issue_title || [];
const deadlines = $json.sla_deadline || [];

if (ids.length === 0) {
  return [{ json: { message: "🎉 You have no open tickets right now!" } }];
}

const list = ids.map((id, i) => `• ${id} — ${titles[i]} (SLA: ${deadlines[i]})`).join('\\n');
const message = `📋 Your Open Tickets\\n\\n${list}`;

return [{ json: { message } }];

const stats = $json;
const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];

const message = `📊 Daily Stats — ${yesterday}

✅ Closed: ${stats.closed_count}
📂 Open: ${stats.open_count}
⚠️ SLA breached (all-time open): ${stats.sla_breached}
⭐ Avg rating: ${stats.avg_rating || 'N/A'}`;

return [{ json: { message } }];

return items.map(item => {
  const now = new Date();

  const date =
    now.getFullYear().toString() +
    String(now.getMonth() + 1).padStart(2, "0") +
    String(now.getDate()).padStart(2, "0");

  const random = Math.floor(1000 + Math.random() * 9000);

  const submittedAt = item.json.submittedAt;

  // ISO timestamp (used for SLA calculations)
  item.json.opened_at = new Date(submittedAt).toISOString();

  // Human-readable IST (used for display)
  item.json.opened_at_ist = new Date(submittedAt).toLocaleString("en-IN", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });

  item.json.ticket_id = `TKT-${date}-${random}`;
  item.json.status = "Open";

  return item;
});
